@namespace sv_a61daa9818b94fec9148fdf3d2c51389.Components.Pages.Apply

<div class="work-entry-form border rounded p-3 mb-3">
    <div class="d-flex justify-content-between align-items-center mb-2">
        <h6 class="mb-0">Position @(Index + 1)</h6>
        @if (ShowRemove)
        {
            <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="row g-3">
        <div class="col-md-6">
            <label class="form-label">Company Name</label>
            <input type="text" class="form-control" value="@Company"
                   @onchange="e => { Company = (string?)e.Value ?? string.Empty; NotifyChanged(); }" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Job Title</label>
            <input type="text" class="form-control" value="@Title"
                   @onchange="e => { Title = (string?)e.Value ?? string.Empty; NotifyChanged(); }" />
        </div>
        <div class="col-md-4">
            <label class="form-label">Start Date</label>
            <input type="date" class="form-control" value="@StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => { StartDate = DateTime.Parse((string?)e.Value ?? DateTime.Today.ToString("yyyy-MM-dd")); NotifyChanged(); }" />
        </div>
        <div class="col-md-4">
            <label class="form-label">End Date</label>
            <input type="date" class="form-control" value="@(EndDate?.ToString("yyyy-MM-dd") ?? "")"
                   disabled="@IsCurrent"
                   @onchange="e => { EndDate = string.IsNullOrEmpty((string?)e.Value) ? null : DateTime.Parse((string)e.Value); NotifyChanged(); }" />
        </div>
        <div class="col-md-4 d-flex align-items-end">
            <div class="form-check">
                <input type="checkbox" class="form-check-input" id="@($"current-{Index}")" checked="@IsCurrent"
                       @onchange="e => { IsCurrent = (bool)(e.Value ?? false); if (IsCurrent) EndDate = null; NotifyChanged(); }" />
                <label class="form-check-label" for="@($"current-{Index}")">Currently employed here</label>
            </div>
        </div>
        <div class="col-12">
            <label class="form-label">Description</label>
            <textarea class="form-control" rows="3" value="@Description"
                      @onchange="e => { Description = (string?)e.Value ?? string.Empty; NotifyChanged(); }"></textarea>
        </div>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryData> OnChanged { get; set; }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync(new WorkEntryData(Company, Title, StartDate, EndDate, IsCurrent, Description));
    }

    public record WorkEntryData(string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description);
}

@namespace sv_a61daa9818b94fec9148fdf3d2c51389.Components.Pages.Apply

<div class="reference-form border rounded p-3 mb-3">
    <div class="d-flex justify-content-between align-items-center mb-2">
        <h6 class="mb-0">Reference @(Index + 1)</h6>
        @if (ShowRemove)
        {
            <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="row g-3">
        <div class="col-md-6">
            <label class="form-label">Name</label>
            <input type="text" class="form-control" value="@Name"
                   @onchange="e => { Name = (string?)e.Value ?? string.Empty; NotifyChanged(); }" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Relationship</label>
            <input type="text" class="form-control" value="@Relationship"
                   @onchange="e => { Relationship = (string?)e.Value ?? string.Empty; NotifyChanged(); }" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Email</label>
            <input type="email" class="form-control" value="@Email"
                   @onchange="e => { Email = (string?)e.Value ?? string.Empty; NotifyChanged(); }" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Phone</label>
            <input type="tel" class="form-control" value="@Phone"
                   @onchange="e => { Phone = (string?)e.Value ?? string.Empty; NotifyChanged(); }" />
        </div>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Name { get; set; } = "";
    [Parameter] public string Relationship { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<ReferenceData> OnChanged { get; set; }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync(new ReferenceData(Name, Relationship, Email, Phone));
    }

    public record ReferenceData(string Name, string Relationship, string Email, string Phone);
}

