@namespace sv_a61daa9818b94fec9148fdf3d2c51389.Components.Pages.Apply

<nav class="step-indicator mb-4">
    <div class="d-flex justify-content-between position-relative">
        @for (int i = 0; i < Steps.Length; i++)
        {
            var stepIndex = i;
            var isCompleted = stepIndex < CurrentStep;
            var isCurrent = stepIndex == CurrentStep;
            var isFuture = stepIndex > CurrentStep;

            <div class="step-item text-center flex-fill @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "dimmed" : "")"
                 @onclick="() => HandleStepClick(stepIndex)"
                 style="cursor: @(isCompleted ? "pointer" : "default")">
                <div class="step-circle mx-auto mb-1 rounded-circle d-flex align-items-center justify-content-center
                    @(isCurrent ? "bg-primary text-white" : isCompleted ? "bg-success text-white" : "bg-secondary text-white")"
                     style="width: 36px; height: 36px; font-size: 0.85rem;">
                    @if (isCompleted)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <small class="@(isFuture ? "text-muted" : "")">@Steps[stepIndex]</small>
            </div>
        }
    </div>
</nav>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly string[] Steps = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private async Task HandleStepClick(int stepIndex)
    {
        if (stepIndex < CurrentStep)
        {
            await OnStepClicked.InvokeAsync(stepIndex);
        }
    }
}

