@namespace sv_a61daa9818b94fec9148fdf3d2c51389.Components.Pages.Apply

<div class="cover-letter-step">
    <h4 class="mb-3">Cover Letter</h4>

    <div class="mb-2">
        <textarea class="form-control" rows="12" value="@CoverLetter"
                  @onchange="e => CoverLetter = (string?)e.Value ?? string.Empty"
                  @oninput="e => CoverLetter = (string?)e.Value ?? string.Empty"
                  maxlength="2000"></textarea>
