                   disabled="@IsCurrent"
                   @onchange="e => { EndDate = string.IsNullOrEmpty((string?)e.Value) ? null : DateTime.Parse((string)e.Value); NotifyChanged(); }" />
        </div>
        <div class="col-md-4 d-flex align-items-end">
            <div class="form-check">
                <input type="checkbox" class="form-check-input" id="@($"current-{Index}")" checked="@IsCurrent"
                       @onchange="e => { IsCurrent = (bool)(e.Value ?? false); if (IsCurrent) EndDate = null; NotifyChanged(); }" />
                <label class="form-check-label" for="@($"current-{Index}")">Currently employed here</label>
            </div>
        </div>
        <div class="col-12">
            <label class="form-label">Description</label>
            <textarea class="form-control" rows="3" value="@Description"
                      @onchange="e => { Description = (string?)e.Value ?? string.Empty; NotifyChanged(); }"></textarea>
        </div>
    </div>
</div>

@code {
